import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState(null);

  const token = localStorage.getItem('token');

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);
      const res = await fetch('http://localhost/api/comandes', {
        headers: {
          Accept: 'application/json',
          Authorization: token ? `Bearer ${token}` : undefined,
        },
      });
      if (!res.ok) throw new Error('Error al obtenir les comandes');
      const data = await res.json();
      setOrders(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      console.error(err);
      setError(err.message || 'Error al obtenir les comandes');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const handleDelete = async (id) => {
    if (!token) { alert('No estás autenticado. Inicia sesión primero.'); return; }
    if (!window.confirm('Segur que vols eliminar aquesta comanda?')) return;
    try {
      const res = await fetch(`http://localhost/api/comandes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' }
      });
      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error eliminant comanda');
      setOrders(orders.filter(o => o.id !== id));
      alert(data.missatge);
    } catch (err) {
      alert(err.message);
    }
  };

  const openEditModal = (order) => {
    setEditingOrder({ ...order });
    setShowModal(true);
  };

  const handleChange = (e) => {
    setEditingOrder({ ...editingOrder, [e.target.name]: e.target.value });
  };

  const handleSave = async () => {
    if (!token) { alert('No estás autenticado. Inicia sesión primero.'); return; }
    try {
      const res = await fetch(`http://localhost/api/comandes/${editingOrder.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(editingOrder)
      });
      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error actualitzant comanda');
      setOrders(orders.map(o => o.id === editingOrder.id ? editingOrder : o));
      setShowModal(false);
    } catch (err) {
      alert(err.message);
    }
  };


  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (orders.length === 0) {
    return <p className="mt-3">No hi ha comandes disponibles</p>;
  }

  return (
    <div className="mt-4">
      <h2>Llista de Comandes</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Client</th>
            <th>Proveïdor</th>
            <th>Tipus</th>
            <th>Data</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((order) => (
            <tr key={order.id}>
              <td>{order.id}</td>
              <td>{order.client?.nom || 'Desconegut'}</td>
              <td>{order.proveidor?.nom || 'Desconegut'}</td>
              <td>{order.tipus}</td>
              <td>{new Date(order.data).toLocaleDateString('ca-ES')}</td>
              <td>
                <Button variant="danger" size="sm" onClick={() => handleDelete(order.id)}>
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>


    </div>
  );
}

export default OrdersList;
